 void globalScaleBarUsesCurrentLatitude(){ga::Site site;site.lat=21.0288;site.lon=105.8525;site.boundary=ga::circleBoundary(500);const QSize size(1100,800);for(const auto latitude:{-75.,0.,21.,40.,80.}){ga::Camera c;c.mode="2d";c=ga::cameraAtGeographicView(site,c,size,latitude,-74,17);const double actual=ga::groundMetresPerPixel(site,c,size,{550,400}),expected=360*111320*std::cos(latitude*M_PI/180)/(256*std::pow(2,17));QVERIFY(std::abs(actual/expected-1)<.00005);}}

 void sharedViewPreservesWorldwideCenterAndScale(){
  ga::Site site;site.lat=21.0288;site.lon=105.8525;site.boundary=ga::circleBoundary(500);const QSize size(1100,800);
  for(const auto &id:QStringList{"axonometric","isometric","perspective","one-point","two-point","2d"})for(const auto &center:QVector<QPointF>{{105.8525,21.0288},{-74.006,40.7128},{151.2093,-33.8688},{179.999,0},{-179.999,0},{0,85},{0,-85}})for(const auto zoom:{2.,6.,12.,16.,20.}){
   ga::Camera c;c.preset(id=="2d"?"isometric":id);if(id=="2d")c.mode="2d";c=ga::cameraAtGeographicView(site,c,size,center.y(),center.x(),zoom);const auto actual=ga::contextCamera(site,c,size);QVERIFY(std::abs(actual.lat-center.y())<1e-9);QVERIFY(std::abs(actual.lon-center.x())<1e-9);QVERIFY2(std::abs(actual.zoom+1-zoom)<.00002,qPrintable(id+" scale "+QString::number(actual.zoom+1)+" expected "+QString::number(zoom)));
   const auto restored=ga::Camera::fromJson(c.toJson());QVERIFY(std::abs(restored.panX-c.panX)<1e-8);QVERIFY(std::abs(restored.panY-c.panY)<1e-8);QVERIFY(std::abs(restored.zoom-c.zoom)<1e-10);
  }
 }
 void worldCameraKeepsNearbyLandmarksPrecise(){
  ga::Site site;site.lat=21.0288;site.lon=105.8525;site.boundary=ga::circleBoundary(500);const QSize size(1100,800);
  for(const auto &center:QVector<QPointF>{{-74.006,40.7128},{179.99999,0},{-179.99999,80}}){
   ga::Camera c;c.preset("perspective");c=ga::cameraAtGeographicView(site,c,size,center.y(),center.x(),19);const auto m=ga::sceneCameraMatrix(site,c,1100./800);const auto context=ga::contextCamera(site,c,size);
   for(const auto &offset:QVector<QPointF>{{0,0},{.00005,.00005},{-.00004,-.00003}}){auto ll=center+offset;ll.setX(std::remainder(ll.x(),360.));const auto local=ga::localPoint(ll.x(),ll.y(),site),plane=ga::scenePlanePoint(local,site,c);QVERIFY(plane.manhattanLength()<100);const auto clip=m*QVector4D(plane.x(),plane.y(),0,1);const QPointF screen((clip.x()/clip.w()+1)*size.width()/2.,(1-clip.y()/clip.w())*size.height()/2.);auto actual=ga::localFromScenePlane(ga::groundOnMapPlane(m,size,screen),site,c);auto difference=ga::scenePlanePoint(actual,site,c)-plane;QVERIFY(QLineF({},difference).length()<.001);
    const double world=512*std::pow(2,context.zoom),longitude=context.lon+std::remainder(ll.x()-context.lon,360.),coordinate[4]={(longitude+180)/360*world,(.5-std::asinh(std::tan(ll.y()*M_PI/180))/(2*M_PI))*world,0,1};double q[4]={};for(int r=0;r<4;++r)for(int k=0;k<4;++k)q[r]+=context.projection[k*4+r]*coordinate[k];QVERIFY(std::abs(q[0]/q[3]-clip.x()/clip.w())*size.width()/2<.002);QVERIFY(std::abs(q[1]/q[3]-clip.y()/clip.w())*size.height()/2<.002);
   }
  }
 }
 void explodedSharedViewUsesActualStackHeight(){ga::Site site;site.boundary=ga::circleBoundary(500);for(const auto &id:QStringList{"isometric","perspective","two-point"}){ga::Camera c;c.preset(id);c.exploded=true;c.stackHeight=320;for(const auto z:{2.,12.,16.,19.}){c=ga::cameraAtGeographicView(site,c,{1100,800},40.7,-74,z);QVERIFY(std::abs(ga::contextCamera(site,c,{1100,800}).zoom+1-z)<.0001);}}}

 void explodedSceneDoesNotAllocateEmptyLayers(){ga::Project p;p.site.boundary=ga::circleBoundary(500);ga::Feature f;f.id=f.sourceId="building/1";f.layer="buildings";f.tags={{"building","yes"}};f.height=10;f.heightSource="recorded";f.rings={QPolygonF{{0,0},{20,0},{20,20},{0,20}}};p.features={f};const QVector<ga::Layer> layers={{"water","Nước","Water",Qt::blue},{"buildings","Nhà","Buildings",Qt::white},{"trees","Cây","Trees",Qt::green}};ga::Camera camera;camera.exploded=true;camera.separation=200;const auto mesh=ga::buildMesh(p,layers,ga::paletteFor("graphite"),camera);for(const auto &v:mesh.triangles)QVERIFY(v.z<11);}
 void cameraMatchesActualWebAdapter(){QFile file(QString::fromUtf8(GA_CAMERA_FIXTURE));QVERIFY(file.open(QIODevice::ReadOnly));const auto cases=QJsonDocument::fromJson(file.readAll()).object()["cases"].toArray();QCOMPARE(cases.size(),20);for(const auto &value:cases){const auto row=value.toObject();ga::Site site;site.lat=row["latitude"].toDouble();site.radius=row["radius"].toDouble();site.boundary=ga::circleBoundary(site.radius);ga::Camera camera;camera.preset(row["id"].toString());camera.zoom=row["zoom"].toDouble();camera.panX=row["pan"].toArray()[0].toDouble();camera.panY=row["pan"].toArray()[1].toDouble();const QSize size(row["width"].toInt(),row["height"].toInt());const auto context=ga::contextCamera(site,camera,size);QVERIFY(std::abs(context.pitch-row["pitch"].toDouble())<1e-7);QVERIFY(std::abs(context.bearing-row["bearing"].toDouble())<1e-7);const auto matrix=ga::sceneCameraMatrix(site,camera,double(size.width())/size.height());for(const auto &item:row["landmarks"].toArray()){const auto landmark=item.toObject();const auto local=landmark["local"].toArray(),expected=landmark["pixel"].toArray();const auto point=ga::scenePlanePoint({local[0].toDouble(),local[1].toDouble()},site,camera);const auto clip=matrix*QVector4D(point.x(),point.y(),local[2].toDouble(),1);const QPointF pixel((clip.x()/clip.w()+1)*size.width()/2.,(1-clip.y()/clip.w())*size.height()/2.);QVERIFY2(QLineF(pixel,{expected[0].toDouble(),expected[1].toDouble()}).length()<.02,qPrintable(row["id"].toString()+" web pixel mismatch"));}}}
 void sceneUnprojectionRetainsGroundPoint(){for(const auto &id:QStringList{"axonometric","isometric","perspective","one-point","two-point"}){ga::Camera camera;camera.preset(id);camera.panX=34;camera.panY=-56;ga::Site site;site.lat=80;site.boundary=ga::circleBoundary(500);const QSize size(1100,800);const auto matrix=ga::sceneCameraMatrix(site,camera,double(size.width())/size.height());for(const auto &point:QVector<QPointF>{{0,0},{100,80},{-220,-140}}){const auto plane=ga::scenePlanePoint(point,site,camera);const auto clip=matrix*QVector4D(plane.x(),plane.y(),0,1);const QPointF screen((clip.x()/clip.w()+1)*size.width()/2.,(1-clip.y()/clip.w())*size.height()/2.);const auto actual=ga::localFromScenePlane(ga::groundOnMapPlane(matrix,size,screen),site,camera);QVERIFY(QLineF(actual,point).length()<.01);}}}
 void mercatorPlaneRoundTrip(){for(const auto latitude:{-80.,-21.,0.,21.0288,37.57,80.}){ga::Site site;site.lat=latitude;for(const auto &p:QVector<QPointF>{{0,0},{-1500,-2000},{2000,1500},{25,-30}}){const auto restored=ga::sitePlanePoint(ga::mapPlanePoint(p,site),site);QVERIFY(QLineF(p,restored).length()<1e-6);}}}
 void contextProjectionMatchesGeographicScene(){for(const auto latitude:{-80.,21.0288,37.57,80.}){ga::Site site;site.lat=latitude;site.boundary=ga::circleBoundary(500);for(const auto &id:QStringList{"axonometric","isometric","perspective","one-point","two-point"}){ga::Camera camera;camera.preset(id);camera.panX=45;camera.panY=-80;camera.zoom=1.3;const QSize size(1100,800);const auto native=ga::contextCamera(site,camera,size);const auto scene=ga::sceneCameraMatrix(site,camera,double(size.width())/size.height());QCOMPARE(native.projection.size(),16);for(const auto &point:QVector<QPointF>{{0,0},{500,-500},{-500,500},{25,30}}){const auto ll=ga::geographicPoint(point,site);const double world=512*std::pow(2,native.zoom),sinLat=std::sin(ll.y()*M_PI/180),coordinate[4]={(ll.x()+180)/360*world,(.5-std::log((1+sinLat)/(1-sinLat))/(4*M_PI))*world,0,1};double clip[4]={};for(int r=0;r<4;++r)for(int c=0;c<4;++c)clip[r]+=native.projection[c*4+r]*coordinate[c];const auto plane=ga::scenePlanePoint(point,site,camera);const auto expected=scene*QVector4D(plane.x(),plane.y(),0,1);QVERIFY(std::abs((clip[0]/clip[3]-expected.x()/expected.w())*size.width()/2)<.05);QVERIFY(std::abs((clip[1]/clip[3]-expected.y()/expected.w())*size.height()/2)<.05);}}}}
 void qualityCountsDistinguishSourceAndEstimates(){ga::Project p;ga::Feature f;f.layer="buildings";f.sourceId="building-1";f.height=12;f.heightSource="google_ai_2023";f.provenance={QJsonObject{{"dataset","Google Open Buildings"},{"record_id","A"}}};p.features.append(f);p.features.append(f);f.sourceId="building-2";f.heightSource="floors_3m";p.features.append(f);f.sourceId="building-3";f.height=std::numeric_limits<double>::quiet_NaN();p.features.append(f);const auto quality=ga::dataQuality(p);QCOMPARE(quality["unique_buildings"].toInt(),3);const auto groups=quality["height_groups"].toObject();QCOMPARE(groups["ai_estimate"].toInt(),1);QCOMPARE(groups["floor_estimate"].toInt(),1);QCOMPARE(groups["unknown_flat"].toInt(),1);QCOMPARE(groups["recorded"].toInt(),0);QCOMPARE(quality["geometry_provenance_records"].toObject()["Google Open Buildings"].toInt(),1);}
 void primitiveSiteShapes(){ga::Site site;site.radius=500;site.shape="square";site.boundary=ga::primitiveBoundary(site);QCOMPARE(std::abs(ga::ringArea(site.boundary)),1000000.);QVERIFY(std::abs(ga::envelopeRadius(site)-std::sqrt(2.)*500)<1e-8);site.shape="rectangle";site.width=800;site.height=400;site.rotation=30;site.boundary=ga::primitiveBoundary(site);QVERIFY(std::abs(std::abs(ga::ringArea(site.boundary))-320000)<1e-7);QVERIFY(ga::selectionError(site).isEmpty());}
 void polygonBoundaryValidation(){QVERIFY(ga::boundaryError(QPolygonF{{0,0},{10,10},{0,10},{10,0}}).contains("crosses"));QVERIFY(!ga::boundaryError(QPolygonF{{0,0},{10,0},{10,10},{10,10},{0,10}}).isEmpty());QVERIFY(ga::boundaryError(QPolygonF{{0,0},{40,0},{40,10},{10,10},{10,40},{0,40}}).isEmpty());ga::Site invalid;invalid.shape="polygon";invalid.boundary=QPolygonF{{-10000,-10000},{10000,-10000},{10000,10000},{-10000,10000}};invalid.rotation=10;QVERIFY(!ga::selectionError(invalid).isEmpty());}
 void lineClipsToConcaveBoundary(){ga::Site site;site.shape="polygon";site.radius=10;site.boundary=QPolygonF{{-10,-10},{10,-10},{10,10},{4,10},{4,-4},{-4,-4},{-4,10},{-10,10}};ga::Feature line;line.geometry=ga::Geometry::Line;line.id="road";line.sourceId="road/original";line.rings={QPolygonF{{-20,0},{20,0}}};const auto parts=ga::clipToSite(line,site);QCOMPARE(parts.size(),2);QCOMPARE(parts[0].sourceId,QString("road/original"));QVERIFY(std::abs(parts[0].rings[0].first().x()+10)<1e-8);QVERIFY(std::abs(parts[0].rings[0].last().x()+4)<1e-8);QVERIFY(std::abs(parts[1].rings[0].first().x()-4)<1e-8);QVERIFY(std::abs(parts[1].rings[0].last().x()-10)<1e-8);line.rings={QPolygonF{{-20,-10},{20,-10}}};QCOMPARE(ga::clipToSite(line,site).size(),1);}
