 void shapeAndProvenanceRoundTrip(){ga::Project p;p.site.shape="rectangle";p.site.width=100;p.site.height=200;p.site.rotation=25;p.site.boundary=ga::primitiveBoundary(p.site);ga::Feature f;f.tags={{"building","house"}};f.properties={{"source_confidence",.81},{"original_tag","kept"}};f.provenance={QJsonObject{{"dataset","OpenStreetMap"},{"record_id","way/123"}}};f.rings={QPolygonF{{0,0},{10,0},{10,10},{0,10}}};p.features={f};const auto restored=ga::Project::fromJson(p.toJson());QCOMPARE(restored.site.shape,QString("rectangle"));QCOMPARE(restored.site.width,100.);QCOMPARE(restored.site.rotation,25.);QCOMPARE(restored.features[0].properties,f.properties);QCOMPARE(restored.features[0].provenance,f.provenance);const auto properties=restored.geoJson()["features"].toArray()[0].toObject()["properties"].toObject();QCOMPARE(properties["source_confidence"].toDouble(),.81);QCOMPARE(properties["sources"].toArray(),f.provenance);}
 void geographicPolygonAndCoverage(){ga::Site frame;QPolygonF points;for(const auto &p:QPolygonF{{-30,-20},{30,-20},{30,20},{-30,20}})points.append(ga::geographicPoint(p,frame));const auto site=ga::siteFromGeographicBoundary(points,"Drawn");QCOMPARE(site.shape,QString("polygon"));QVERIFY(std::abs(std::abs(ga::ringArea(site.boundary))-2400)<.001);ga::Project source;source.site=frame;source.site.radius=50;source.site.shape="square";source.site.boundary=ga::primitiveBoundary(source.site);source.source={{"attribution","Test source"}};ga::Feature f;f.layer="buildings";f.tags={{"building","house"}};f.sourceId="building/record";f.height=12;f.heightSource="recorded";f.rings={QPolygonF{{-45,-45},{45,-45},{45,45},{-45,45}},QPolygonF{{-5,-5},{5,-5},{5,5},{-5,5}}};source.features={f};const auto clipped=ga::reclipProject(source,site);QCOMPARE(clipped.features[0].rings.size(),2);QVERIFY(std::abs(clipped.features[0].area()-2300)<.001);QVERIFY(clipped.source["coverage_complete"].toBool());ga::Site wider=source.site;wider.radius=100;wider.boundary=ga::primitiveBoundary(wider);const auto partial=ga::reclipProject(source,wider);QVERIFY(std::abs(partial.source["coverage_fraction"].toDouble()-.25)<1e-8);QVERIFY(!partial.source["coverage_complete"].toBool());QCOMPARE(partial.features[0].height,12.);ga::Site remote=site;remote.lon+=.1;QVERIFY_EXCEPTION_THROWN(ga::reclipProject(source,remote),std::runtime_error);}
 void overpassRetainsPolygonSelection(){ga::Site site;site.lat=.0003;site.lon=.0003;site.shape="rectangle";site.width=20;site.height=40;site.radius=20;site.boundary=ga::primitiveBoundary(site);const auto root=QJsonDocument::fromJson(R"({"elements":[{"type":"way","id":1,"tags":{"building":"yes"},"geometry":[{"lon":0,"lat":0},{"lon":0.0006,"lat":0},{"lon":0.0006,"lat":0.0006},{"lon":0,"lat":0.0006},{"lon":0,"lat":0}]}]})").object();const auto p=ga::importOverpass(root,site);QCOMPARE(p.site.shape,QString("rectangle"));QCOMPARE(p.site.boundary,site.boundary);QVERIFY(std::abs(p.features[0].area()-800)<1e-6);QVERIFY(!p.features[0].knownHeight());QVERIFY(!p.features[0].provenance.isEmpty());}
 void legacyCameraLabelMatchesItsPose(){auto camera=ga::Camera::fromJson({{"projection","isometric"},{"yaw",35},{"elevation",35.264}});QCOMPARE(camera.yaw,35.);QCOMPARE(camera.projection,QString("axonometric"));camera=ga::Camera::fromJson({{"projection","isometric"},{"yaw",45},{"elevation",35.26438968}});QCOMPARE(camera.projection,QString("isometric"));}
 void isometricHasEqualAxisScale(){ga::Camera c;const auto m=c.matrix(500,1.4);const auto a=m*QVector4D(0,0,0,1);QVector<double> lengths;for(const auto &v:QVector<QVector4D>{{100,0,0,1},{0,100,0,1},{0,0,100,1}}){const auto b=m*v;lengths.append(std::hypot((b.x()/b.w()-a.x()/a.w())*1.4,b.y()/b.w()-a.y()/a.w()));}QVERIFY(std::abs(lengths[0]-lengths[1])<1e-6);QVERIFY(std::abs(lengths[1]-lengths[2])<1e-6);}
 void presentationCatalog(){const auto directory=QFileInfo(QString::fromUtf8(GA_SAMPLE)).dir();ga::loadPresentationCatalog(directory.filePath("presentations.json"));QCOMPARE(ga::palettes().size(),39);QCOMPARE(ga::diagramPresets().size(),20);for(const auto &d:ga::diagramPresets()){QVERIFY(ga::paletteFor(d.id).paper.isValid());QVERIFY(!d.layers.isEmpty());}ga::Feature f;f.layer="trees";f.tags={{"natural","tree"}};QVERIFY(ga::diagramMatches(f,"ga-diagram-planting"));QVERIFY(!ga::diagramMatches(f,"ga-diagram-solid"));f.layer="buildings";f.tags={{"building","yes"}};QVERIFY(ga::diagramMatches(f,"ga-diagram-solid"));}
 void clipPreservesHolesAndSource(){ga::Site site;site.radius=50;site.boundary=ga::circleBoundary(50);ga::Feature f;f.id=f.sourceId="source/1";f.layer="buildings";f.rings={QPolygonF{{-80,-80},{80,-80},{80,80},{-80,80}},QPolygonF{{-10,-10},{10,-10},{10,10},{-10,10}}};auto clipped=ga::clipToSite(f,site);QCOMPARE(clipped.size(),1);QCOMPARE(clipped[0].sourceId,f.sourceId);QCOMPARE(clipped[0].rings.size(),2);QVERIFY(std::abs(clipped[0].area()-(std::abs(ga::ringArea(site.boundary))-400))<.01);QVERIFY(std::abs(ga::meshTopArea(clipped[0])-clipped[0].area())<.01);}
