 void climateCoverageIsExplicit(){const auto directory=QFileInfo(QString::fromUtf8(GA_SAMPLE)).dir();ga::Site hanoi;const auto station=ga::nearestClimate(directory.filePath("climate.json"),hanoi);QVERIFY(!station.isEmpty());QVERIFY(station["distance_km"].toDouble()<=100);const auto climate=station["climate"].toObject();QCOMPARE(climate["monthly"].toArray().size(),12);QVERIFY(climate["monthly"].toArray()[0].toObject()["precipitation"].isNull());ga::Site seoul;seoul.lat=37.57;seoul.lon=126.98;QVERIFY(ga::nearestClimate(directory.filePath("climate.json"),seoul).isEmpty());QVERIFY(ga::environmentFields(directory.filePath("environment"),seoul).isEmpty());}
 void gridNodataStaysTransparent(){QJsonObject f{{"width",2},{"height",2},{"grid",QJsonArray{QJsonArray{0,QJsonValue::Null},QJsonArray{5,10}}},{"statistics",QJsonObject{{"min",0},{"max",10}}}};const auto image=ga::gridImage(f);QCOMPARE(image.size(),QSize(2,2));QCOMPARE(image.pixelColor(1,0).alpha(),0);QCOMPARE(image.pixelColor(0,0).alpha(),255);QVERIFY(image.pixelColor(0,0)!=image.pixelColor(1,1));const auto directory=QFileInfo(QString::fromUtf8(GA_SAMPLE)).dir();const auto fields=ga::environmentFields(directory.filePath("environment"),ga::Site());QVERIFY(fields.size()>=5);for(const auto &field:fields){const auto image=ga::gridImage(field);QVERIFY(!image.isNull());int count=0;for(int y=0;y<image.height();++y)for(int x=0;x<image.width();++x)count+=image.pixelColor(x,y).alpha()!=0;QCOMPARE(count,field["statistics"].toObject()["valid_cells"].toInt());}}
